/* Isolated visual review. No backend calls, credentials, persistence or operational actions. */
'use strict';
const screens = [
  ['overview','Shipping overview','layout'],['create','Create shipment','plus'],['tracking','Shipment tracking','package'],
  ['routes','Route comparison','route'],['crisis','Crisis command','shield'],['twin','Digital twin','layers'],
  ['inventory','Inventory & procurement','box'],['suppliers','Supplier intelligence','building'],['monitoring','Logistics monitoring','globe'],
  ['alerts','Alerts & risk','bell'],['assistant','AI logistics assistant','spark'],['auth','Authentication','lock']
];
const paths = {
  layout:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  package:'<path d="m12 3 9 5v8l-9 5-9-5V8l9-5Zm0 9 9-4M12 12 3 8m9 4v9M7 5.8l9 5"/>',
  box:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M3 11h18M8 7V3h8v4m-6 8h4"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h9a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h9"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
  layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',
  building:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M9 21v-4h6v4M8 7h1m6 0h1M8 11h1m6 0h1"/>',
  globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
  bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9 21h6"/>',
  spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3Z"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
  filter:'<path d="M4 6h16M7 12h10m-7 6h4"/><circle cx="8" cy="6" r="2"/><circle cx="15" cy="12" r="2"/>',
  download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',ship:'<path d="M5 13V7h14v6M9 7V3h6v4m-3 4 9 4-3 5H6l-3-5 9-4Zm0 0v9M3 22l3-2 3 2 3-2 3 2 3-2 3 2"/>',
  truck:'<path d="M3 5h12v12H3V5Zm12 5h4l3 4v3h-7"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',
  plane:'<path d="m22 2-7 20-4-9-9-4L22 2ZM11 13 22 2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
  check:'<path d="m5 12 4 4L19 6"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
  flag:'<path d="M5 21V3m0 1h14l-3 4 3 4H5"/>',chart:'<path d="M3 3v18h18M7 16l5-7 4 3 5-7"/>',
  settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',
  camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3V7Z"/><circle cx="12" cy="14" r="4"/>',
  pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
  refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 14 6M4 12a8 8 0 0 0 14 6"/>',
  file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v5h5M8 12h8m-8 4h6"/>',wind:'<path d="M3 8h12a3 3 0 1 0-3-3M2 12h17a3 3 0 1 1-3 3M4 16h6a3 3 0 1 1-3 3"/>',
  warning:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 3v.1"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'
};
const icon = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const brand = '<span class="brand-mark"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m12 2 10 20h-4L12 9 6 22H2L12 2Z" fill="#e4eaf4"/><path d="m9 19 3-5 3 5" stroke="#8baceb" stroke-width="1.5"/></svg></span>';
const badge=(text,tone='soft')=>`<span class="badge ${tone}">${text}</span>`;
const btn=(text,action='info',value='',primary=false,ico='')=>`<button class="btn ${primary?'primary':''}" data-${action}="${value||text}">${ico?icon(ico):''}${text}</button>`;
const kv=(label,value)=>`<div class="keyval"><span>${label}</span><span>${value}</span></div>`;
const note=(text,tone='')=>`<div class="note ${tone}">${icon('info')}<div>${text}</div></div>`;
const heading=(title,description,actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;
const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div><div class="panel-body">${body}</div></section>`;
const metrics=(items)=>`<div class="metric-row">${items.map(([label,value,sub])=>`<div class="metric"><span>${label}${icon('more')}</span><strong>${value}</strong><small>${sub}</small></div>`).join('')}</div>`;
const tabs=(items,active=0)=>`<div class="tabs">${items.map((x,i)=>`<button class="tab ${i===active?'active':''}" data-tab="${x}">${x}</button>`).join('')}</div>`;
const table=(headers,rows,cls='')=>`<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map((row,i)=>`<tr class="${i===0?'selected-row':''}" data-detail="${i}">${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const check=()=>'<input class="check" type="checkbox" aria-label="Select row">';
const pair=(from='Jebel Ali',to='Doha',labels=['Origin · UAE','Destination · Qatar'])=>`<div class="route-pair"><div><b>${from}</b><small>${labels[0]}</small></div><div class="route-line"></div><div><b>${to}</b><small>${labels[1]}</small></div></div>`;
const field=(label,value,type='text',help='')=>`<div class="field"><label>${label}<input class="input" type="${type}" value="${value}"></label>${help?`<small>${help}</small>`:''}</div>`;
const select=(label,options)=>`<div class="field"><label>${label}<select>${options.map(x=>`<option>${x}</option>`).join('')}</select></label></div>`;
const chart=(kind='stock')=>`<svg class="chart" viewBox="0 0 640 200" role="img" aria-label="Illustrative ${kind==='twin'?'baseline and scenario delivery duration':'inventory projection'} chart"><g class="grid"><path d="M40 30h570M40 75h570M40 120h570M40 165h570"/></g><text x="8" y="34">${kind==='twin'?'48h':'120'}</text><text x="8" y="79">${kind==='twin'?'36h':'80'}</text><text x="8" y="124">${kind==='twin'?'24h':'40'}</text><text x="14" y="169">${kind==='twin'?'12h':'0'}</text><text x="40" y="191">07 Nov</text><text x="170" y="191">09 Nov</text><text x="305" y="191">11 Nov</text><text x="440" y="191">13 Nov</text><text x="570" y="191">15 Nov</text>${kind==='twin'?'<path class="baseline" d="M40 120H610"/><path class="scenario" d="M40 120H178V75H610"/><text x="410" y="64">Scenario: 36 hours</text><text x="410" y="140">Baseline: 24 hours</text>':'<path class="stock" d="M40 53 110 66 180 80 250 93 320 107 390 120 460 134 530 147 610 165"/><path d="M40 131H610" stroke="#bd9e68" stroke-dasharray="5 4"/><text x="450" y="122">Safety stock · 30 units</text><path d="M40 53 110 66 180 80 250 93 320 107 390 120 460 134 530 147 610 165V165H40Z" fill="#81a7e8" opacity=".045"/>'}</svg>`;
function map(type='route',height=260){
  const routes=type!=='monitoring';
  return `<div class="map" style="height:${height}px"><svg class="cartography" viewBox="0 0 800 440" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Illustrative Gulf schematic, not navigational route geometry"><defs><pattern id="grid-${type}" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M50 0H0V50" fill="none" stroke="#293340" stroke-width=".5" opacity=".45"/></pattern></defs><rect width="800" height="440" fill="#11171e"/><rect width="800" height="440" fill="url(#grid-${type})"/><path d="M0 0H250l-12 44-40 37-10 50-22 35-17 48 19 38 24 32 41 14 30-18 15-42 19-24 12 13-4 47-6 30 38 26 73 3 68-14 75-19 84-17 60-26 31-36 22-44 45-26V440H0Z" fill="#1c232b" stroke="#35404e" stroke-width="1.3"/><path d="M315 0H800v181l-55-12-38-31-46-19-24-24-54-5-39-23-75-13-68-20-55-8Z" fill="#1c232b" stroke="#35404e" stroke-width="1.3"/><path d="m303 252 2-29 11-10 5 17-5 30" fill="#252f3a" stroke="#4a5767"/><path d="M60 330 185 310 260 326 385 350 487 324 600 280" fill="none" stroke="#3a414a" stroke-dasharray="3 5"/><g fill="#707e90" font-family="Geist, sans-serif" font-size="13"><text x="96" y="366">Saudi Arabia</text><text x="512" y="60">Iran</text><text x="520" y="343">United Arab Emirates</text><text x="680" y="373">Oman</text><text x="350" y="150" fill="#4c6075" letter-spacing="4">Arabian Gulf</text></g>${routes?`<path d="M594 284 465 330 360 326 313 259" stroke="#7599d4" stroke-width="2.5" fill="none" stroke-dasharray="7 5"/><path d="M594 284Q462 177 313 259" stroke="#667486" stroke-width="1.5" fill="none" stroke-dasharray="3 6"/>${type==='crisis'?'<path d="M634 181 720 221" stroke="#c09665" stroke-width="16" opacity=".18"/><path d="M634 181 720 221" stroke="#c09665" stroke-width="2" stroke-dasharray="5 4"/><text x="574" y="163" fill="#d4b682" font-size="12">Hypothetical corridor restriction</text>':''}`:'<g fill="#7e9abd"><path d="m430 230 4 9-8-1Z"/><path d="m471 208 4 9-8-1Z"/><path d="m524 239 4 9-8-1Z"/><path d="m374 219 4 9-8-1Z"/><path d="m573 205 4 9-8-1Z"/></g><path d="m337 287 10-5-4 11-1-6Z" fill="#b3bdcd"/>'}<g fill="#b1c9f0" stroke="#1b2635" stroke-width="4"><circle cx="313" cy="259" r="6"/><circle cx="594" cy="284" r="6"/></g><g font-family="Geist, sans-serif" font-size="12" fill="#bdc9db"><text x="270" y="287">Doha</text><text x="602" y="307">Jebel Ali</text><text x="167" y="204">Bahrain</text></g></svg><div class="map-overlay">${badge(type==='crisis'?'Hypothetical network':'Illustrative schematic')}${type==='monitoring'?badge('Not cargo positions'):''}</div><div class="map-controls"><button data-info="Map zoom" aria-label="Zoom in">+</button><button data-info="Map zoom" aria-label="Zoom out">−</button></div><span class="map-caption">Schematic only · Not navigational geometry · MapLibre / OpenFreeMap planned</span></div>`;
}
function shell(current){
  const nav=(ids)=>ids.map(id=>{const s=screens.find(s=>s[0]===id);return `<a class="nav-link ${current===id?'active':''}" href="#${id}" ${current===id?'aria-current="page"':''}>${icon(s[2])}<span>${s[1].replace('Shipping overview','Overview').replace('Shipment tracking','Shipments').replace('AI logistics assistant','AI assistant').replace('Inventory & procurement','Inventory').replace('Supplier intelligence','Suppliers').replace('Logistics monitoring','Monitoring')}</span>${id==='alerts'?'<span class="count">3</span>':''}</a>`}).join('');
  document.getElementById('sidebar').innerHTML=`<a class="brand" href="#overview">${brand}<strong>ALTAIR</strong></a><div class="workspace-switch"><span class="avatar">NW</span><div><b>Northstar workspace</b><small>Illustrative business account</small></div>${icon('down')}</div>${current==='auth'?'<div class="auth-sidebar-note"><h3>Your logistics workspace</h3>Shipping operations, grounded in evidence.<div class="divider"></div>Compare routes<br>Track recorded milestones<br>Plan for disruptions<br>Understand supply risk</div>':`<nav aria-label="Main navigation"><div class="nav-group"><div class="nav-heading">Operations</div>${nav(['overview','tracking','routes','inventory','suppliers','alerts'])}</div><div class="nav-group"><div class="nav-heading">Intelligence</div>${nav(['crisis','twin','monitoring','assistant'])}<button class="nav-link" style="width:100%;background:none;border:0;text-align:left;font:inherit" data-modal="resilience">${icon('chart')}<span>National resilience</span></button><button class="nav-link" style="width:100%;background:none;border:0;text-align:left;font:inherit" data-modal="compliance">${icon('shield')}<span>Cargo compliance</span></button></div></nav>`}<div class="sidebar-bottom"><div class="sidebar-note"><b>${icon('layers')} One workspace. Two contexts.</b>Operational records stay separate from hypothetical scenarios.</div><a class="account" href="#auth"><span class="avatar">NA</span><div><span class="small">Northstar Admin</span><div class="tiny muted">Demo identity</div></div>${icon('settings')}</a></div>`;
  document.getElementById('topbar').innerHTML=`<div class="breadcrumb">${icon('layout')}<span>${['crisis','twin','monitoring','assistant'].includes(current)?'Intelligence':'Workspace'}</span><span>/</span><b>${screens.find(s=>s[0]===current)[1]}</b></div><button class="top-search" data-command>${icon('search')}Search or run a command<kbd>Ctrl K</kbd></button><button class="icon-btn" data-go="alerts" aria-label="Open alerts">${icon('bell')}</button><span class="avatar" style="width:26px;height:26px">NA</span>`;
}
const shipmentRows=[
  ['ALT-1042','Medical supplies','Jebel Ali → Doha','In transit','blue','09 Nov, 14:00','Manual update'],
  ['ALT-1041','Industrial filters','Muscat → Doha','Quote requested','amber','Not confirmed','Request record'],
  ['ALT-1040','Packaging materials','Riyadh → Doha','Planned','soft','11 Nov, 09:00','Owner estimate'],
  ['ALT-1039','Spare components','Mumbai → Doha','Delayed','amber','Under review','Manual update'],
  ['ALT-1038','Cold-chain packaging','Doha → Al Khor','Delivered','green','06 Nov, 16:20','Owner recorded'],
  ['ALT-1037','Electrical assemblies','Dubai → Doha','Draft','soft','Not set','Draft order'],
  ['ALT-1036','Workshop equipment','Dammam → Doha','In transit','blue','10 Nov, 12:00','Manual update']
];
function overview(){return heading('Shipping overview','Your shipments, decisions and exceptions in one place.',btn('Export view','info','Export preview',false,'download')+btn('Create shipment','go','create',true,'plus'))+
  metrics([['Active shipments','4','In this illustrative portfolio'],['Awaiting quotations','1','External response required'],['Needs attention','2','1 delay · 1 overdue update'],['Delivered','1','In the visible seven-order sample']])+
  `<div class="split"><div>${tabs(['All shipments <span>7</span>','Needs attention <span>2</span>','Drafts <span>1</span>'])}<div class="toolbar"><div class="search-field">${icon('search')}<input data-filter placeholder="Search shipments…" aria-label="Search shipments"></div>${btn('Filters','modal','filters',false,'filter')}<span class="spacer"></span>${btn('Columns','info','Table columns',false,'settings')}</div><section class="panel">${table(['Reference / cargo','Route','Status','Expected arrival'],shipmentRows.map(r=>[`${r[0]}<span class="table-sub">${r[1]}</span>`,r[2],badge(r[3],r[4]),r[5]]),'shipment-table')}<div class="table-footer"><span>7 illustrative records · Not live portfolio totals</span><div class="actions"><span>1 of 1</span>${icon('chevron')}</div></div></section><div class="section-space">${panel('Decisions needing attention',`<div class="list-item">${icon('clock')}<div><h3>Review the delayed delivery for ALT-1039</h3><p>Compare alternative routes before requesting a change.</p></div><a class="end blue" href="#routes">Review ${icon('chevron')}</a></div><div class="list-item">${icon('file')}<div><h3>Quotation request awaiting a partner response</h3><p>ALT-1041 · A request is not a confirmed booking.</p></div><span class="end">Pending</span></div>`,badge('2 open'))}</div></div><aside class="inspector"><div class="inspect-title"><h2>ALT-1042</h2>${badge('In transit','blue')}</div><div class="inspect-section"><span class="tiny muted">Medical supplies · Illustrative record</span>${pair()}<div class="progress"><span style="width:46%"></span></div>${kv('Transport','Sea + road')}${kv('Cargo','40 cartons / 1,000 kg')}${kv('Expected arrival','09 Nov, 14:00')}<p>Owner-maintained estimate, not a carrier commitment.</p></div>${map('overview',185)}<div class="inspect-section"><h3>Latest recorded milestone</h3><div class="list-item">${icon('ship')}<div><h3>Departure recorded</h3><p>07 Nov, 08:30 · Manual / shipment owner</p></div></div>${note('No verified cargo position is available. Vessel positions are shown separately in Monitoring.')}</div><div class="inspect-section">${btn('View shipment','go','tracking',true,'arrow')}</div></aside></div>`;}
function createShipment(){return heading('Create shipment','Define your cargo requirements before comparing transport options.',badge('Draft order')+btn('Save draft','info','Draft preview saved locally only',false,'file'))+
  `<div class="stepper"><div class="step active"><b>1</b>Shipment details</div><div class="step-divider"></div><div class="step"><b>2</b>Compare routes</div><div class="step-divider"></div><div class="step"><b>3</b>Request quotation</div><span style="margin-left:auto" class="tiny muted">Booking requires external confirmation</span></div><div class="split"><form id="shipment-form" class="panel"><div class="form-section"><h2>Where is your shipment going?</h2><p>Choose catalog locations with supported transport connections.</p><div class="form-grid">${select('Origin',['Jebel Ali · United Arab Emirates','Muscat · Oman','Riyadh · Saudi Arabia'])}${select('Destination',['Doha · Qatar','Al Khor · Qatar'])}</div></div><div class="form-section"><h2>Cargo details</h2><p>Accurate cargo requirements help exclude unsuitable transport options.</p><div class="form-grid">${select('Product',['Medical supplies · Illustrative catalog','Industrial filters'])}${field('Your reference','NS-2026-042')}${field('Quantity','40','number','Cartons · Unit retained throughout the order')}${field('Total weight (kg)','1000','number')}${field('Length × width × height (cm)','120 × 80 × 100')}${field('Total volume (m³)','4.8','number')}<div class="field full-span"><label>Handling requirements</label><div class="chips"><button type="button" class="chip active" data-chip>${icon('check')}Ambient</button><button type="button" class="chip" data-chip>Fragile</button><button type="button" class="chip" data-chip>Temperature controlled</button><button type="button" class="chip" data-chip>Hazardous goods</button></div></div></div></div><div class="form-section"><h2>Delivery requirements</h2><div class="form-grid" style="margin-top:14px">${field('Cargo ready date','2026-11-08','date')}${field('Requested delivery by','2026-11-12','date')}</div><div class="tick-line" style="margin-top:14px">${icon('info')}Requested dates are requirements, not confirmed schedules.</div></div><div class="form-actions">${btn('Cancel','go','overview')}<button class="btn primary" type="submit">Compare routes ${icon('arrow')}</button></div></form><aside class="stack">${panel('Order summary',`${pair()}${kv('Product','Medical supplies')}${kv('Quantity','40 cartons')}${kv('Mass / volume','1,000 kg / 4.8 m³')}${kv('Handling','Ambient')}${kv('Delivery requested','12 Nov 2026')}<div class="divider"></div><p>All fields are illustrative. No shipping record will be created during design review.</p>`)}${panel('What happens next?',`<div class="list-item">${icon('route')}<div><h3>Compare supported alternatives</h3><p>Review estimated cost, duration and risks.</p></div></div><div class="list-item">${icon('file')}<div><h3>Request a quotation</h3><p>Your selected plan goes into a request workflow.</p></div></div><div class="list-item">${icon('check')}<div><h3>Record external confirmation</h3><p>A carrier or logistics partner confirms the arrangement.</p></div></div>`)}${note('Cargo restrictions must be checked against current source-backed guidance.','amber')}</aside></div>`;}
function tracking(){return heading('ALT-1042 · Medical supplies','Shipping / Shipments / ALT-1042 · Illustrative shipment record',btn('Record milestone','modal','milestone',false,'plus')+btn('Compare reroutes','go','routes',true,'route'))+
 `<div class="split"><div class="stack"><section class="panel"><div class="panel-head"><div class="actions">${badge('In transit','blue')}<span class="small muted">Owner-maintained status</span></div><span class="tiny muted">Last entry: 07 Nov, 08:30</span></div><div class="panel-body">${pair('Jebel Ali','Doha',['United Arab Emirates','Qatar'])}</div><div class="tracking-steps">${['Order created','Departure recorded','In transit','Arrival','Delivered'].map((x,i)=>`<div class="tracking-step ${i<2?'done':i===2?'active':''}"><i></i>${x}</div>`).join('')}</div>${map('tracking',240)}</section>${panel('Milestone history',`<div class="timeline"><div class="event"><time>07 Nov · 08:30</time><h3>Departure recorded ${badge('Manual')}</h3><p>Shipment owner · Jebel Ali · Reference document attached</p></div><div class="event"><time>06 Nov · 15:10</time><h3>Cargo handed over ${badge('Manual')}</h3><p>Shipment owner · 40 cartons / 1,000 kg declared</p></div><div class="event"><time>05 Nov · 11:20</time><h3>Shipping order created</h3><p>Northstar Admin · Source: internal order record</p></div></div>`,btn('View audit history','modal','history'))}</div><aside class="stack"><div class="inspector"><div class="inspect-title"><h2>Shipment details</h2>${icon('package')}</div><div class="inspect-section">${kv('Reference','ALT-1042')}${kv('Carrier reference','Not provided')}${kv('Transport legs','Sea → road')}${kv('Estimated arrival','09 Nov, 14:00')}${kv('Estimate source','Shipment owner')}${kv('Last cargo location','No verified observation')}${note('AIS vessel observations do not confirm this cargo’s location.')}</div><div class="inspect-section"><h3>Rerouting request</h3>${badge('Awaiting external confirmation','amber')}<p style="margin-top:12px">Request RR-008 proposes a land alternative. The confirmed shipment plan has not changed.</p>${kv('Requested','07 Nov, 09:15')}${kv('Partner response','Not received')}${btn('View request','modal','reroute')}</div></div>${panel('Delivery requirements',`${kv('Product','Medical supplies')}${kv('Handling','Ambient')}${kv('Requested by','12 Nov 2026')}${kv('Linked inventory','Doha distribution stock')}`)}${note('Illustrative timeline. Production milestones will retain author, source and observation time.')}</aside></div>`;}
function routeOption(name,mode,cost,time,risk,selected=false,conditional=false){return `<article class="route-option ${selected?'selected':''}"><header>${icon(mode)}<h3>${name}</h3>${badge(conditional?'Conditional':'Illustrative estimate',conditional?'amber':'soft')}</header><div class="route-stats"><div><small>Estimated cost</small><b>${cost}</b></div><div><small>Transit time</small><b>${time}</b></div><div><small>Risk index</small><b>${risk}</b></div></div><p>${conditional?'Capacity confirmation required · Ranking is provisional':'Includes declared cost components · Not a carrier quotation'}</p></article>`;}
function routes(){return heading('Compare transportation options','ALT-1042 · Jebel Ali → Doha · 1,000 kg · Ambient cargo',btn('Edit requirements','go','create',false,'settings')+btn('Request quotation','modal','quote',true,'file'))+
 `<div class="toolbar" style="padding-top:0">${badge('All results below are illustrative','amber')}<span class="spacer"></span><span class="small muted">Optimize for</span><div class="chips"><button class="chip active" data-chip>Balanced</button><button class="chip" data-chip>Cost</button><button class="chip" data-chip>Time</button><button class="chip" data-chip>Risk</button></div></div><div class="split"><div class="stack"><section class="panel">${map('route',300)}<div class="panel-body"><div class="legend"><span><i style="background:#7599d4"></i>Selected alternative</span><span><i style="background:#667486"></i>Other illustrative option</span><span>Geometry gaps remain explicit in production</span></div></div></section><div class="inline-title"><h2>3 transport alternatives</h2><span class="tiny muted">Compared within the same currency · USD</span></div>${table(['Alternative','Estimated cost','Duration','Risk index','Feasibility'],[[`${icon('truck')} Land · Direct`,'USD 900','20–24 h','0.20',badge('Feasible','green')],[`${icon('ship')} Sea + road`,'USD 640','32–40 h','0.35',badge('Conditional','amber')],[`${icon('plane')} Air + road`,'USD 1,850','8–12 h','0.15',badge('Feasible','green')]])}${note('Risk is an index, not a disruption probability. Missing costs, mixed currencies and unknown durations are never replaced with zero.')}</div><aside class="inspector"><div class="inspect-title"><h2>Selected alternative</h2>${badge('Land','blue')}</div><div class="inspect-section">${routeOption('Direct land connection','truck','USD 900','20–24 h','0.20',true)}${pair()}${kv('Cargo requirement','1,000 kg / ambient')}${kv('Cost completeness','Declared components complete')}${kv('Source nature','Hypothetical fixture')}${kv('Confidence','0.50 · Assumption quality')}</div><div class="inspect-section"><h3>Before requesting transport</h3><div class="list-item">${icon('check')}<div><h3>Fits declared cargo constraints</h3><p>Capacity and handling evaluated on fixture data.</p></div></div><div class="list-item">${icon('warning')}<div><h3>External confirmation still needed</h3><p>No carrier price, availability or schedule is verified.</p></div></div></div><div class="inspect-section"><div class="actions">${btn('Save preference','info','Preferred route preview')}${btn('Request quote','modal','quote',true)}</div><p style="margin-top:12px">For an existing shipment, submit a reroute request instead.</p><button class="btn ghost" data-modal="reroute">Request reroute ${icon('arrow')}</button></div></aside></div>`;}
function crisis(){return heading('Crisis command','Civilian logistics resilience · Explore disruption scenarios without changing operations.',btn('Scenario history','go','twin',false,'clock')+btn('Run simulation','go','twin',true,'layers'))+
 `<div class="review-banner">${icon('shield')}<strong>Hypothetical planning context</strong><span>These controls do not declare real closures or redirect shipments.</span></div><div class="split"><div class="stack"><div class="three-cols"><article class="scenario-card selected">${icon('ship','amber')}<h3>Corridor restriction</h3><p>Assess alternatives if a selected connection becomes unavailable.</p><footer>${badge('Selected assumption','amber')}</footer></article><article class="scenario-card">${icon('building')}<h3>Supplier interruption</h3><p>Inspect linked receipts and potential sourcing alternatives.</p><footer>${btn('Configure','modal','supplier-scenario')}</footer></article><article class="scenario-card">${icon('box')}<h3>Essential-goods demand</h3><p>Evaluate explicitly declared demand against available supply.</p><footer>${btn('Configure','modal','demand-scenario')}</footer></article></div><section class="panel"><div class="panel-head"><h2>Scenario network</h2>${badge('7-day planning horizon')}</div>${map('crisis',290)}<div class="panel-body"><div class="legend"><span><i style="background:#d4b276"></i>Hypothetical restriction</span><span><i style="background:#7599d4"></i>Alternative connection</span></div></div></section>${panel('Operational evidence stays separate',`<div class="list-item">${icon('file')}<div><h3>News signals require verification</h3><p>A report about regional tension is not evidence that a corridor is closed.</p></div>${badge('Potential')}</div><div class="list-item">${icon('shield')}<div><h3>Civilian supply continuity</h3><p>Assess essential-goods replenishment and feasible transport alternatives.</p></div><a href="#inventory" class="end blue">Inventory ${icon('chevron')}</a></div>`)}</div><aside class="inspector"><div class="inspect-title"><h2>Scenario configuration</h2>${icon('settings')}</div><div class="inspect-section">${field('Scenario name','Gulf corridor contingency')}${select('Affected connection',['Illustrative sea connection A'])}<div class="field" style="margin-top:16px"><label>Availability assumption</label><div class="chips"><button class="chip active" data-chip>Closed</button><button class="chip" data-chip>Reduced capacity</button></div></div><div class="divider"></div><div class="field"><label>Alternate land transit multiplier</label><div class="range-line"><input type="range" min="1" max="3" step=".1" value="1.5" aria-label="Transit time multiplier"><span>1.5×</span></div></div><div class="field" style="margin-top:18px"><label>Alternate land cost multiplier</label><div class="range-line"><input type="range" min="1" max="3" step=".1" value="1.2" aria-label="Cost multiplier"><span>1.2×</span></div></div></div><div class="inspect-section"><h3>Baseline and scope</h3>${kv('Snapshot','07 Nov 2026, 09:00')}${kv('Horizon','168 hours')}${kv('Network','Illustrative UAE–Qatar graph')}${kv('Scenario owner','Current account')}${note('A frozen baseline makes repeat executions comparable. No operational records are changed.')}</div><div class="inspect-section">${btn('Review simulation','go','twin',true,'arrow')}</div></aside></div>`;}
function twin(){return heading('Digital twin simulation','Gulf corridor contingency · Baseline and scenario comparison',btn('New scenario','go','crisis',false,'plus')+btn('Replay snapshot','info','Replay preview',true,'refresh'))+
 `<div class="review-banner">${icon('layers')}<strong>Hypothetical result</strong><span>Frozen baseline: 07 Nov 2026, 09:00 · Illustrative engine output</span><span style="margin-left:auto">twin 1.0.0</span></div>`+
 metrics([['Returned alternatives','3 → 2','Sea connection excluded by scenario'],['Preferred cost change','+ USD 180','900 baseline → 1,080 scenario'],['Maximum transit change','+12 h','24 baseline → 36 scenario'],['Supply shortage','10 kg','Scenario balance · Baseline 0 kg']])+
 `<div class="split"><div class="stack">${panel('Preferred land route · duration comparison',`${chart('twin')}<div class="legend"><span><i></i>Baseline</span><span><i style="background:#d4b276"></i>Scenario</span></div>`,badge('Fixed snapshot'))}${table(['Measure','Baseline','Scenario','Change'],[['Cost · USD','900.00','1,080.00','+180.00'],['Duration · hours','20–24','30–36','×1.5'],['Available supply · kg','100','80','−20'],['Explicit demand · kg','90','90','Unchanged'],['Shortage · kg','0','10','+10']])}${note('Illustrative arithmetic: max(90 − 80, 0) = 10 kg shortage. Supply units are never converted implicitly. Scenario assumptions do not confirm real inventory availability.')}</div><aside class="inspector"><div class="inspect-title"><h2>Calculation details</h2>${icon('file')}</div><div class="inspect-section"><h3>Applied modifications</h3><div class="list-item">${icon('ship')}<div><h3>Sea connection closed</h3><p>Excluded from the scenario graph only.</p></div></div><div class="list-item">${icon('clock')}<div><h3>Land duration ×1.5</h3><p>20–24 hours becomes 30–36 hours.</p></div></div><div class="list-item">${icon('route')}<div><h3>Land cost ×1.2</h3><p>USD 900 becomes USD 1,080.</p></div></div><div class="list-item">${icon('box')}<div><h3>Inventory reduced by 20 kg</h3><p>Explicit assumption on a linked stock record.</p></div></div></div><div class="inspect-section"><h3>Replay context</h3>${kv('Baseline','Immutable snapshot')}${kv('Engine','altair-twin-1.0.0')}${kv('Routing','altair-routing-1.0.0')}${kv('Input / snapshot hashes','Available in real execution')}${kv('Operational mutations','None')}</div><div class="inspect-section">${btn('Review inventory impact','go','inventory',true,'arrow')}<div style="margin-top:8px">${btn('Explain trade-offs','go','assistant',false,'spark')}</div></div></aside></div>`;}
function inventory(){return heading('Inventory & procurement','Track owned stock, understand demand and review replenishment requirements.',btn('Record movement','modal','movement',false,'plus')+btn('Review replenishment','modal','procurement',true,'box'))+
 metrics([['Products in view','5','Illustrative stock records'],['Below safety stock','1','Medical supply packs · 30-unit threshold'],['Replenishment reviews','2','Recommendations, not purchase orders'],['Unverified receipts','1','Excluded from available supply']])+
 `<div class="split"><div class="stack"><div>${tabs(['Stock overview','Demand commitments','Movement history'])}<div class="toolbar"><div class="search-field">${icon('search')}<input data-filter placeholder="Search products…" aria-label="Search products"></div>${btn('Doha warehouse','info','Warehouse selector',false,'down')}<span class="spacer"></span>${btn('Filters','modal','filters',false,'filter')}</div><section class="panel">${table(['Product','On hand','Reserved','Available','Coverage'],[['Medical supply packs','24 units','4 units','20 units',badge('2 days','amber')],['Industrial filters','100 units','20 units','80 units','8 days'],['Packaging cartons','2,400 units','400 units','2,000 units','20 days'],['Workshop seals','680 units','80 units','600 units','30 days'],['Electrical connectors','1,200 units','200 units','1,000 units','Unknown']])}</section></div>${panel('Industrial filters · available-stock projection',`${chart()}<div class="legend"><span><i style="background:#82a7e8"></i>Available units · Example assumption</span><span><i style="background:#bd9e68"></i>Safety stock</span></div><p style="margin-top:12px">80 available units, explicit demand 10 units/day, no eligible receipts. Illustration reaches zero after 8 days.</p>`,badge('Estimate'))}</div><aside class="inspector"><div class="inspect-title"><h2>Replenishment review</h2>${badge('Action needed','amber')}</div><div class="inspect-section"><h3>Industrial filters</h3>${kv('Physical stock','100 units')}${kv('Reserved','20 units')}${kv('Available','80 units')}${kv('Daily demand','10 units · Explicit assumption')}${kv('Lead time','5 days · Assumption')}${kv('Safety stock','30 units')}${kv('Coverage after lead','10 days')}<div class="divider"></div><div class="mini-stat"><span>Suggested procurement quantity</span><b>100 <span class="small muted">units</span></b><small>max(30 + 10 × 15 − 80, 0)</small></div></div><div class="inspect-section"><h3>Supply verification</h3>${note('Unverified incoming stock is not credited to the forecast. Confirm quantity and validity before inclusion.','amber')}<p style="margin-top:12px">This estimate does not place an order or guarantee supplier availability.</p></div><div class="inspect-section">${btn('Find supplier candidates','go','suppliers',true,'building')}<div style="margin-top:8px">${btn('Test disruption impact','go','crisis',false,'layers')}</div></div></aside></div>`;}
function suppliers(){return heading('Supplier intelligence','Find evidence-backed catalog matches and review sourcing uncertainty.',btn('Import dependencies','modal','resilience',false,'chart')+btn('Refine search','modal','supplier-search',true,'search'))+
 `<div class="toolbar" style="padding-top:0"><div class="search-field" style="width:300px">${icon('search')}<input data-filter value="" placeholder="Industrial filters" aria-label="Search supplier candidates"></div><button class="chip active" data-chip>Qatar</button><button class="chip active" data-chip>Catalog product match</button>${btn('Capabilities','info','Capability filters',false,'down')}<span class="spacer"></span><span class="tiny muted">Illustrative directory · 4 candidates</span></div><div class="split"><div class="stack"><section class="panel">${table(['Supplier / location','Match evidence','Stock','Catalog score'],[['Example Gulf Industrial<span class="table-sub">Doha, Qatar · Industrial components</span>',badge('Catalog match','green'),badge('Unverified'),'130'],['Example Peninsula Supply<span class="table-sub">Al Wakrah, Qatar · Equipment distributor</span>',badge('Potential match','amber'),badge('Unverified'),'30'],['Example Doha Trading<span class="table-sub">Doha, Qatar · General sourcing</span>',badge('Potential match','amber'),badge('Unverified'),'30'],['Example North Supply<span class="table-sub">Al Khor, Qatar · Industrial parts</span>',badge('Potential match','amber'),badge('Unverified'),'30']],'supplier-row')}<div class="table-footer">Fictional organizations for layout review · Matching score is not a reliability rating</div></section>${panel('Sourcing review checklist',`<div class="list-item">${icon('file')}<div><h3>Verify product specification and catalog evidence</h3><p>A supplier listing can support a match without confirming current inventory.</p></div></div><div class="list-item">${icon('box')}<div><h3>Request current quantity and lead time</h3><p>Only a recorded, valid confirmation can support an incoming-stock estimate.</p></div></div><div class="list-item">${icon('shield')}<div><h3>Review handling and compliance requirements</h3><p>Keep source references attached to the sourcing decision.</p></div></div>`)}${panel('Import dependency context',`<p>Historical import concentration provides context, not current stock availability. Select a reporting period, HS edition, source and currency before calculating exposure.</p><div class="actions" style="margin-top:16px">${badge('Historical data')}${btn('Explore national resilience','modal','resilience',false,'arrow')}</div>`)}</div><aside class="inspector"><div class="inspect-title"><h2>Supplier evidence</h2>${icon('building')}</div><div class="inspect-section"><span class="avatar" style="width:40px;height:40px;font-size:14px">GI</span><h2 style="margin-top:12px">Example Gulf Industrial</h2><p class="small muted" style="margin-top:4px">Fictional supplier · Doha, Qatar</p><div class="chips" style="margin-top:14px">${badge('Catalog match','green')}${badge('Stock unverified','amber')}</div></div><div class="inspect-section">${kv('Product','Industrial filters')}${kv('Country match','Qatar')}${kv('Current availability','Not verified')}${kv('Price / lead time','Not provided')}<div class="evidence"><strong>${icon('file')} Illustrative catalog evidence</strong><p>Product listing · Example observation 01 Nov 2026</p><p>A current confirmed catalog match requires valid source evidence. No real supplier is represented here.</p></div></div><div class="inspect-section"><h3>Next action</h3><p>Prepare a sourcing inquiry and record the supplier’s response. Nothing is ordered automatically.</p><div style="margin-top:14px">${btn('Prepare inquiry','modal','supplier-inquiry',true,'mail')}</div></div></aside></div>`;}
function monitoring(){return heading('Logistics monitoring','Public transport observations and environmental context, separate from cargo tracking.',btn('Source status','modal','sources',false,'info')+btn('Refresh observations','info','Observation refresh preview',false,'refresh'))+
 `<div class="toolbar" style="padding-top:0"><div class="chips"><button class="chip active" data-chip>${icon('ship')}Maritime</button><button class="chip" data-chip>${icon('plane')}Aviation</button><button class="chip" data-chip>${icon('wind')}Weather</button><button class="chip" data-chip>${icon('camera')}Cameras</button></div><span class="spacer"></span>${badge('Illustrative points · No connected feeds','amber')}</div><div class="split"><div class="stack"><section class="panel">${map('monitoring',390)}<div class="panel-body"><div class="legend"><span><i style="background:#7e9abd"></i>Example vessel symbols</span><span><i style="background:#b3bdcd"></i>Example aircraft symbol</span><span>Not verified observations</span></div></div></section>${table(['Source','Information','Connection','Freshness'],[['AISStream','Vessel observations',badge('Not configured'),'Unavailable'],['OpenSky','Aircraft observations',badge('Not configured'),'Unavailable'],['Open-Meteo','Weather / marine forecasts',badge('Not checked'),'Not verified'],['Authorized cameras','Public visual conditions',badge('No source'),'Unavailable']])}</div><aside class="stack">${panel('Observation inspector',`<div class="empty-state">${icon('ship')}<h3>No live vessel selected</h3><p>The map uses illustrative symbols for visual review. Production will show provider IDs, observed times, source coverage and freshness.</p></div>${note('A vessel observation is not cargo tracking. A verified shipment–vessel association is required.')}`)}${panel('Camera & visual conditions',`<div class="empty-state">${icon('camera')}<h3>No authorized camera available</h3><p>Add only reviewed public or explicitly authorized sources. Private port or industrial CCTV is not accessed.</p></div><div class="divider"></div><p>Camera images do not verify cargo contents, customs clearance or route availability.</p>`)}${panel('Data interpretation',`${kv('Positions','Public observations')}${kv('Weather','Model forecasts')}${kv('Event time','Separate from sync time')}${kv('Stale data','Labeled, never refreshed by inference')}`)}</aside></div>`;}
function alerts(){const rows=[['amber','clock','Shipment update is overdue','ALT-1042 · Last owner update needs review','Operational alert','12 min ago'],['amber','box','Potential stockout before replenishment','Medical supply packs · Based on declared demand','Forecast estimate','35 min ago'],['red','route','Transport disruption needs verification','Potential regional signal · No closure confirmation','Potential risk signal','1 h ago']];return heading('Alerts & risk intelligence','Review the evidence, understand affected records and decide what to do next.',btn('Monitoring settings','modal','monitoring-config',false,'settings')+btn('Evaluate now','info','Monitoring evaluation preview',true,'refresh'))+
 `<div class="split"><div>${tabs(['Open <span>3</span>','Acknowledged','Resolved','Risk signals'])}<div class="toolbar">${btn('All severities','info','Severity filter',false,'filter')}${btn('All sources','info','Source filter',false,'down')}<span class="spacer"></span><span class="tiny muted">Illustrative alert inbox</span></div><section class="panel">${rows.map((r,i)=>`<article class="alert-row ${i===0?'selected':''}" data-alert="${i}">${icon(r[1],r[0])}<div><h3>${r[2]}</h3><p>${r[3]}</p><div class="alert-meta">${badge(r[4])}<span>Requires review</span></div></div><time>${r[5]}</time></article>`).join('')}</section><div class="section-space">${panel('Evidence coverage',`<div class="two-cols"><div><h3>Source uncertainty is visible</h3><p style="margin-top:8px">Missing provider data does not mean conditions are safe. Last-known evidence retains its observation and expiry times.</p></div><div><h3>Hypotheses stay isolated</h3><p style="margin-top:8px">Scenario closures never become operational alerts or confirmed geopolitical facts.</p></div></div>`)}</div></div><aside class="inspector"><div class="inspect-title"><h2>Alert details</h2>${badge('High priority','amber')}</div><div class="inspect-section"><h2 style="font-size:17px">Shipment update is overdue</h2><p style="margin-top:10px">The illustrative record has not received an owner update within its configured monitoring interval.</p>${kv('Affected record','ALT-1042')}${kv('Rule','Stale shipment update')}${kv('Threshold','24 hours')}${kv('Source','Owner record timestamp')}${kv('State','Open')}<div class="evidence"><strong>Evidence, not a delivery conclusion</strong><p>An overdue update does not itself mean the cargo is delayed, missing or damaged.</p></div></div><div class="inspect-section"><h3>Recommended action</h3><p>Request an attributed update from the shipment owner or carrier. Record the response as a milestone.</p><div class="actions" style="margin-top:16px">${btn('View shipment','go','tracking',true,'arrow')}</div></div><div class="inspect-section"><div class="actions">${btn('Acknowledge','info','Acknowledged in design preview only')}${btn('Resolve','modal','resolve')}</div><p style="margin-top:12px">Acknowledging records review. Resolving does not alter the shipment or source evidence.</p></div></aside></div>`;}
function assistant(){return heading('AI logistics assistant','Ask about your records. Inspect the calculations and assumptions behind every answer.',btn('Open command palette','command','',false,'search'))+
 `<div class="chat-shell"><section class="chat"><div class="panel-head"><h2>Gulf corridor contingency</h2>${badge('Illustrative conversation')}</div><div class="chat-body"><div class="message"><span class="avatar">NA</span><div class="message-body"><header><b>You</b><time>09:42</time></header><p>What changes in my supply plan if the sea connection is unavailable?</p></div></div><div class="message">${brand}<div class="message-body"><header><b>ALTAIR</b>${badge('Hypothetical analysis')}</header><p>In this illustrative scenario, the preferred land alternative remains available, but costs more and takes longer. The inventory assumption also creates a 10 kg shortfall.</p><div class="finding"><h3>${icon('route')} Route comparison <span class="muted">[1]</span></h3><p>USD 900 → USD 1,080. Maximum transit duration 24 → 36 hours. These are scenario estimates, not carrier quotations.</p></div><div class="finding"><h3>${icon('box')} Supply impact <span class="muted">[2]</span></h3><p>80 kg available against 90 kg explicit demand. Shortage = 10 kg. Supplier stock remains unverified.</p></div><div class="note" style="margin-top:14px">${icon('shield')}<div>Review the scenario and supplier evidence before requesting a route or sourcing change. No operational plan has been modified.</div></div><div class="actions" style="margin-top:16px">${btn('Review scenario','go','twin')}${btn('Find suppliers','go','suppliers')}</div></div></div></div><div class="chat-compose"><div class="compose-input"><textarea aria-label="Ask ALTAIR" placeholder="Ask about a shipment, forecast or scenario…"></textarea><footer><span class="tiny muted">Preview only · No model request is sent</span>${btn('Ask ALTAIR','info','AI preview only — no model connected',true,'arrow')}</footer></div></div></section><aside class="stack">${panel('Evidence used',`<div class="evidence" style="margin-top:0"><strong>[1] Scenario route comparison</strong><p>Deterministic routing · Frozen snapshot</p><div style="margin-top:8px">${badge('Hypothetical')}</div></div><div class="evidence"><strong>[2] Scenario supply balance</strong><p>Product / unit-specific calculation</p><div style="margin-top:8px">${badge('Hypothetical')}</div></div><p style="margin-top:16px">Real responses link each finding to current tool evidence. This conversation is a visual illustration, not generated analysis.</p>`)}${panel('Assumptions to review',`${kv('Sea connection','Closed')}${kv('Land transit','×1.5')}${kv('Land cost','×1.2')}${kv('Inventory reduction','20 kg')}${kv('Demand baseline','90 kg')}${btn('Inspect exact inputs','go','crisis',false,'file')}`)}${panel('When AI is unavailable',`<p>The routing, forecasting and digital twin tools remain usable without an LLM provider.</p><div class="actions" style="margin-top:14px">${btn('Open tools','command','',false,'search')}</div>`)}</aside></div>`;}
function auth(){return `<div class="auth-layout"><section class="auth-intro">${brand}<h1>A clearer view of what moves your business.</h1><p>Manage shipments, evaluate transport alternatives and prepare for disruption in one evidence-backed workspace.</p><div class="auth-diagram"><div class="actions">${icon('package')}<span class="small">From requirement to delivery</span></div>${pair('Origin','Destination',['Your shipping requirement','Your business'])}<div class="chips">${badge('Compare')}${badge('Request')}${badge('Track')}</div></div><p style="font-size:11px;margin-top:24px">MES Youth Hackathon 2026 · Smarter Qatar<br>Built by a three-member student team.</p></section><section><form class="auth-form" id="auth-form"><h2>Sign in to ALTAIR</h2><p>Your shipments and scenarios, in one place.</p>${field('Email address','','email')}${field('Password','','password')}<div style="text-align:right;margin:-5px 0 20px"><button class="btn ghost small" type="button" data-info="Password recovery preview">Forgot password?</button></div><button class="btn primary full" type="submit">Sign in ${icon('arrow')}</button><div class="or-line">Account access</div><p class="small muted" style="text-align:center;margin-bottom:0">Need an account? <button class="btn ghost small" type="button" data-info="Account creation preview">Create account</button></p><div class="note" style="margin-top:24px">${icon('lock')}<div>Design preview only. Do not enter real credentials. No authentication request is sent.</div></div></form><p class="auth-foot">Production sign-in uses the existing Supabase session and<br>owner-scoped access to private records.</p></section></div>`;}
const renderers={overview,create:createShipment,tracking,routes,crisis,twin,inventory,suppliers,monitoring,alerts,assistant,auth};
const descriptions={
  quote:['Request quotation','The preferred alternative and cargo requirements would be attached to an owned quotation request. Its status remains “Awaiting partner response”; a request is not a carrier booking.','Quotation request preview'],
  reroute:['Rerouting request · RR-008','Proposed alternative: direct land. Reason: review transport disruption. Status: awaiting external confirmation. The current confirmed route is unchanged. Production will require an authorized response and retain an immutable change history.','Review proposal'],
  milestone:['Record an attributed milestone','Production will capture the event, occurrence time, recorded time, author, location and supporting reference. Manual entries are explicitly labeled and do not claim carrier verification.','Milestone form preview'],
  history:['Shipment audit history','05 Nov · Order created. 06 Nov · Owner recorded handover. 07 Nov · Owner recorded departure. 07 Nov · Reroute request submitted; no route change confirmed. All entries are illustrative.','Audit history preview'],
  procurement:['Replenishment request','Review product, units, required quantity and supplier evidence. An inquiry is not a purchase order and does not increase available stock.','Procurement preview'],
  movement:['Record inventory movement','Choose receipt, consumption or adjustment; enter quantity, unit and occurrence time. The existing ledger uses a stable idempotency key and retains immutable movements.','Movement preview'],
  'supplier-inquiry':['Prepare supplier inquiry','Ask for current product availability, quantity, lead time and a quotation. Catalog evidence is not stock confirmation. No inquiry is sent during review.','Inquiry preview'],
  'supplier-search':['Supplier search criteria','Use catalog product, HS classification and edition, country and capability filters. Matching is evidence-backed; it does not scrape or invent supplier stock.','Search preview'],
  'supplier-scenario':['Supplier interruption assumption','Select an existing supplier and inspect established dependencies. Only linked receipts are affected; unrelated suppliers and operational records remain unchanged.','Assumption preview'],
  'demand-scenario':['Demand change assumption','Select a product, exact unit, baseline demand and finite additional demand within the scenario horizon. Unknown baselines must be supplied explicitly.','Assumption preview'],
  'monitoring-config':['Monitoring configuration','Select owned shipments and inventory, explicit connection mappings and thresholds. Evaluations use the existing monitoring engine; missing evidence never automatically means recovery.','Configuration preview'],
  sources:['Source configuration and freshness','AISStream and OpenSky credentials were not found under the checked local names. No live sources were enabled. Weather and marine data are forecasts. Cameras require a reviewed public or authorized source.','Provider status preview'],
  resolve:['Resolve alert','Production records the authorized resolution and audit time. A recurring active condition can reopen an episode on the next monitoring evaluation. This does not change the shipment itself.','Resolution preview'],
  filters:['Filter this view','Production filters will use the actual supported API contract or clearly labeled loaded-row filtering. Page-scoped results will not be represented as global totals.','Filter preview'],
  resilience:['National resilience · Historical import dependencies','Preserved advanced capability. Select Qatar trade source, reporting period, exact HS classification/edition and currency. Review observed origin shares and concentration alongside explicit scenario exposure. Historical trade value is not physical stock or a current national shortage probability.','Dependency analysis preview'],
  compliance:['Cargo compliance · Source-backed guidance','Preserved advanced capability. Review cargo class, origin, destination, mode and handling restrictions using dated authoritative references. Unverified or absent guidance is shown as unavailable. ALTAIR does not issue customs clearance or infer restrictions from news.','Compliance review preview']
};
let current='overview',lastFocus=null;
function fit(){const capture=new URLSearchParams(location.search).has('capture')||document.body.classList.contains('capture');document.body.classList.toggle('capture',capture);const scale=capture?1:Math.min((innerWidth-32)/1440,(innerHeight-90)/900,1);const viewport=document.getElementById('viewport');viewport.style.width=`${1440*scale}px`;viewport.style.height=`${900*scale}px`;document.getElementById('artboard').style.transform=`scale(${scale})`;}
function render(){current=location.hash.slice(1)||'overview';if(!renderers[current])current='overview';shell(current);document.getElementById('page').innerHTML=renderers[current]();document.getElementById('page').scrollTop=0;document.getElementById('screen-select').value=current;document.title=`ALTAIR — ${screens.find(s=>s[0]===current)[1]} · Design review`;closeOverlay(false);fit();}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.style.display='none';},4000);}
function closeOverlay(restore=true){document.getElementById('overlay-root').innerHTML='';if(restore&&lastFocus?.isConnected)lastFocus.focus();}
function openModal(key){lastFocus=document.activeElement;const [title,body,action]=descriptions[key]||['Design preview','This control illustrates the approved workflow. It does not call a backend service or save a real record.','Review'];document.getElementById('overlay-root').innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-close aria-label="Close dialog">${icon('x')}</button></div><div class="dialog-body">${body}<div class="divider"></div>${badge('Design preview · No operational action','amber')}</div><div class="dialog-footer">${btn('Close','close')}${btn(action,'info','Preview only — no data was sent or saved.',true)}</div></section></div>`;document.querySelector('[data-close]').focus();}
function command(){lastFocus=document.activeElement;document.getElementById('overlay-root').innerHTML=`<div class="overlay" style="padding-top:110px"><section class="dialog command" role="dialog" aria-modal="true" aria-label="Global command palette"><div class="command-search">${icon('search')}<input id="command-input" placeholder="Search shipments, pages or actions…" aria-label="Search commands"><button class="icon-btn" data-close aria-label="Close palette"><kbd>Esc</kbd></button></div><div class="command-tabs">${badge('All','blue')}${badge('Shipments')}${badge('Intelligence')}${badge('Actions')}</div><div class="command-results"><div class="command-label">Quick actions</div>${[['create','plus','Create a shipping order','Shipping'],['routes','route','Compare transportation options','Intelligence'],['tracking','package','ALT-1042 · Medical supplies','Shipment'],['crisis','shield','Configure a crisis scenario','Hypothetical'],['twin','layers','Gulf corridor contingency','Digital twin'],['inventory','box','Review inventory and replenishment','Operations'],['assistant','spark','Ask the logistics assistant','AI']].map(([id,ico,text,type])=>`<button class="command-item" data-go="${id}">${icon(ico)}${text}<small>${type}</small></button>`).join('')}<div id="command-empty" class="empty-filter hidden">No matching commands. Try a shipment or page name.</div></div><div class="command-footer"><span><kbd>↑</kbd> <kbd>↓</kbd> Navigate</span><span><kbd>Enter</kbd> Open</span><span><kbd>Esc</kbd> Close</span></div></section></div>`;document.getElementById('command-input').focus();}
document.getElementById('screen-select').innerHTML=screens.map(([id,name],i)=>`<option value="${id}">${String(i+1).padStart(2,'0')} · ${name}</option>`).join('');
document.getElementById('screen-select').addEventListener('change',e=>location.hash=e.target.value);
document.getElementById('next').onclick=()=>{location.hash=screens[(screens.findIndex(s=>s[0]===current)+1)%screens.length][0];};
document.getElementById('previous').onclick=()=>{location.hash=screens[(screens.findIndex(s=>s[0]===current)+screens.length-1)%screens.length][0];};
document.getElementById('actual-size').onclick=()=>{location.href=`${location.pathname}?capture=1#${current}`;};
document.addEventListener('click',e=>{
  const target=e.target.closest('[data-go],[data-info],[data-modal],[data-command],[data-close],[data-chip],[data-tab],[data-detail],[data-alert]');if(!target)return;
  if(target.hasAttribute('data-go')){closeOverlay(false);location.hash=target.dataset.go;}
  else if(target.hasAttribute('data-modal'))openModal(target.dataset.modal);
  else if(target.hasAttribute('data-command'))command();
  else if(target.hasAttribute('data-close'))closeOverlay();
  else if(target.hasAttribute('data-info')){e.preventDefault();toast(`${target.dataset.info} · Design preview; no backend action.`);}
  else if(target.hasAttribute('data-chip')){e.preventDefault();target.classList.toggle('active');}
  else if(target.hasAttribute('data-tab')){target.parentElement.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===target));toast('Tab appearance preview. Production content will come from the corresponding backend records.');}
  else if(target.hasAttribute('data-alert')){target.parentElement.querySelectorAll('.alert-row').forEach(x=>x.classList.toggle('selected',x===target));toast('Alert selection preview. Inspector shows the illustrative overdue-update record.');}
  else if(target.hasAttribute('data-detail')&&e.target.type!=='checkbox'){target.parentElement.querySelectorAll('tr').forEach(x=>x.classList.toggle('selected-row',x===target));toast('Row selection preview. Inspectors show the named illustrative example.');}
});
document.addEventListener('input',e=>{
  if(e.target.matches('[data-filter]')){const q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));}
  if(e.target.type==='range')e.target.nextElementSibling.textContent=`${e.target.value}×`;
  if(e.target.id==='command-input'){let count=0;document.querySelectorAll('.command-item').forEach(item=>{item.hidden=!item.textContent.toLowerCase().includes(e.target.value.toLowerCase());item.style.display=item.hidden?'none':'';if(!item.hidden)count++;});document.getElementById('command-empty').classList.toggle('hidden',count>0);}
});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='shipment-form')location.hash='routes';else if(e.target.id==='auth-form'){e.target.reset();toast('Authentication preview only. No credentials were submitted.');}});
document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();command();}
  if(e.key==='Escape')closeOverlay();
  const dialog=document.querySelector('[role="dialog"]');if(!dialog)return;
  if(e.key==='Tab'){const focusable=[...dialog.querySelectorAll('button,input,a')].filter(x=>!x.hidden&&x.style.display!=='none');if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus();}}
  if(['ArrowDown','ArrowUp'].includes(e.key)&&dialog.classList.contains('command')){e.preventDefault();const items=[...dialog.querySelectorAll('.command-item')].filter(x=>!x.hidden);if(items.length){const index=items.indexOf(document.activeElement);items[(index+(e.key==='ArrowDown'?1:items.length-1)+items.length)%items.length].focus();}}
  if(e.key==='Enter'&&e.target.id==='command-input'){e.preventDefault();document.querySelector('.command-item:not([hidden])')?.click();}
});
window.addEventListener('hashchange',render);window.addEventListener('resize',fit);render();
